namespace Sample.Server.Messaging;

public sealed class Installer
{
    public void Install(IServiceCollection services)
    {
        services.AddBroker();
        services.AddBrokerExtension<BrokerExtension>();
    }
}

public sealed class BrokerExtension : IBrokerExtension
{
    public void Configure(BrokerOptions opts)
    {
        opts.UseQueueTransport(Connect);
        opts.PublishMessage<OrderPlaced>().ToExchange("order-placed");
    }
}
